INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.72.1',
  '2026-08-05',
  'Фиксы настройки групп товаров: молчаливые кнопки и слипшиеся группы',
  E'Если несколько групп товаров смотрели в одну категорию, диаграмма схлопывалась в один сектор, и было непонятно, почему статистики по группам нет. Теперь об этом честно предупреждает плашка с кнопкой «Создать типовые категории и разнести группы» — она заводит шесть категорий и пересобирает уже разобранные чеки.\n\nКнопка «Создать группы» больше не молчит, если привязки уже есть. Смена привязки группы теперь сразу пересобирает разобранные чеки: раньше настройка выглядела сломанной — переставили группу, а отчёт не менялся. Ручная разметка товаров при пересборе сохраняется.',
  E'Три недоработки одного корня: настройка групп меняла только соответствие, но не данные.\n\n1. SeedItemGroups пропускал коды с существующей привязкой и возвращался молча — из интерфейса починить «все группы в одной категории» было нечем. Добавлен reset: перепривязывает все группы к своим категориям (find-or-create по имени).\n2. Ни seed, ни PUT /finance/item-groups/{code} не трогали уже разобранные чеки. Добавлен Importer.ClassifyAll — вызывается после любой правки соответствия и возвращает число пересобранных чеков в ответ, чтобы интерфейс показал результат.\n3. Совпадение категорий у нескольких групп ничем не подсвечивалось. На экране «Группы» появилась плашка со списком слипшихся групп.\n\nПоймано typecheck-ом при правке: кнопка с @click="seed" после смены сигнатуры на seed(reset = false) передавала бы событие клика как флаг сброса — то есть безобидная кнопка стала бы разрушительной.\n\nРучная разметка указывает на категорию, а не на группу, поэтому смена привязки её не двигает — это осознанно и проверено: после пересбора правило и его сумма остались на месте.\n\nПроверено воспроизведением ситуации с прода: все шесть групп в одной категории -> отчёт показывал один сектор -> reset вернул четыре группы с верными суммами (Продукты 45772.17, Алкоголь 5903.8, Бытовая химия 4219.89, Доставка 2697), «не разобрано» 0, итог 58592.86 не изменился.'
);
-- +goose StatementEnd

